import * as THREE from 'three';
import {mergeGeometries} from '../room-compare/vendor/three/addons/utils/BufferGeometryUtils.js';
export function createBatch(){const groups=new Map();let inputMeshes=0;
 function add(root,chunkIndex=null){root.updateMatrixWorld(true);const disposable=new Set();root.traverse(mesh=>{if(!mesh.isMesh)return;const materials=Array.isArray(mesh.material)?mesh.material:[mesh.material];if(materials.length!==1)throw Error('Batch expects single-material shell primitives');const material=materials[0];if(!groups.has(material))groups.set(material,[]);const target=groups.get(material),count=mesh.isInstancedMesh?mesh.count:1;inputMeshes++;for(let i=0;i<count;i++){let g=mesh.geometry.index?mesh.geometry.toNonIndexed():mesh.geometry.clone();const transform=mesh.matrixWorld.clone();if(mesh.isInstancedMesh){const m=new THREE.Matrix4();mesh.getMatrixAt(i,m);transform.multiply(m);}g.applyMatrix4(transform);for(const key of Object.keys(g.attributes))if(!['position','normal','uv','chunk','color'].includes(key))g.deleteAttribute(key);if(material.vertexColors&&!g.attributes.color)g.setAttribute('color',new THREE.Float32BufferAttribute(new Float32Array(g.attributes.position.count*3).fill(1),3));if(!material.vertexColors&&g.attributes.color)g.deleteAttribute('color');if(!g.attributes.normal)g.computeVertexNormals();if(!g.attributes.uv)g.setAttribute('uv',new THREE.BufferAttribute(new Float32Array(g.attributes.position.count*2),2));if(chunkIndex!==null)g.setAttribute('chunk',new THREE.Float32BufferAttribute(new Float32Array(g.attributes.position.count).fill(chunkIndex),1));g.clearGroups();target.push(g);}disposable.add(mesh.geometry);});for(const g of disposable)g.dispose();root.clear();}
 function finish(){const result=new THREE.Group();for(const [material,geometries] of groups){if(!geometries.length)continue;const g=mergeGeometries(geometries,false);for(const source of geometries)source.dispose();if(!g)throw Error('Geometry merge failed');g.computeBoundingSphere();const mesh=new THREE.Mesh(g,material);mesh.castShadow=mesh.receiveShadow=true;result.add(mesh);}groups.clear();return {group:result,inputMeshes};}
 return {add,finish};
}
